#include "conjunto.h"

void inicializar(TConjunto *c) {
  c->cantidad = 0;
}

TBool pertenece(TConjunto c, int x) {
  for (int i = 0; i < c.cantidad; i++) {
    if (c.elementos[i] == x) {
      return VERDADERO;
    }
  }
  return FALSO;
}

void agregar(TConjunto *c, int x) {
  if (pertenece(*c, x) == FALSO) {
    c->elementos[c->cantidad] = x;
    c->cantidad = c->cantidad + 1;
  }
}

int cardinal(TConjunto c) {
  return c.cantidad;
}

void eliminar(TConjunto *c, int x) {
  for (int i = 0; i < c->cantidad; i++) {
    if (c->elementos[i] == x) {
      c->elementos[i] = c->elementos[c->cantidad - 1];
      c->cantidad = c->cantidad - 1;
      return;
    }
  }
}

TConjunto unir(TConjunto a, TConjunto b) {
  TConjunto r = a;

  for (int i = 0; i < b.cantidad; i++) {
    agregar(&r, b.elementos[i]);
  }
  return r;
}

